@require_POST
def attach_asset_to_ticket(request, ticket_id):
    ticket = get_object_or_404(SupportTicket, id=ticket_id, tenant=request.tenant)
    asset_id = request.POST.get('asset_id')
    asset = get_object_or_404(DigitalAsset, id=asset_id, tenant=request.tenant)
    ticket.attachments.add(asset)
    return JsonResponse({'status': 'asset linked'})
